'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useSession, signOut } from 'next-auth/react';
import { Home, ShoppingBag, ListOrdered, Heart, Wallet, Settings, LogOut } from 'lucide-react';

// Definisikan menu beserta peran yang diizinkan untuk mengaksesnya
const menuItems = [
  { icon: Home, text: 'Home', href: '/', roles: ['owner', 'kasir'] },
  { icon: ShoppingBag, text: 'Products', href: '/products', roles: ['owner', 'kasir'] },
  { icon: ListOrdered, text: 'Order List', href: '/orders', roles: ['owner', 'kasir'] },
  { icon: Heart, text: 'Favorite', href: '/favorites', roles: ['owner'] },
  { icon: Wallet, text: 'Payment', href: '/payment', roles: ['owner'] },
];

const Sidebar = () => {
  const pathname = usePathname();
  const { data: session } = useSession();
  
  // Dapatkan role user dari data sesi
  const userRole = session?.user?.role as string;

  return (
    <aside className="w-64 bg-white p-6 flex flex-col justify-between">
      <div>
        <h1 className="text-2xl font-bold mb-10 ml-4 text-foreground">N</h1>
        <nav>
          <ul>
            {menuItems.map((item) => {
              // --- Logika Filter Berdasarkan Role ---
              // Jika item ini punya batasan role DAN role user tidak termasuk di dalamnya,
              // maka jangan tampilkan menu ini (return null).
              if (item.roles && !item.roles.includes(userRole)) {
                return null;
              }

              // --- Logika untuk Menu Aktif ---
              const isActive = pathname === item.href;

              return (
                <li key={item.text}>
                  <Link
                    href={item.href}
                    className={`flex items-center py-3 px-4 my-1 rounded-lg transition-colors
                      ${ isActive
                          ? 'bg-accent text-foreground font-semibold'
                          : 'text-text-secondary hover:bg-gray-100 '
                      }`}
                  >
                    <item.icon className="w-5 h-5 mr-3" />
                    {item.text}
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>
      </div>
      <div>
        {/* Tombol Log Out sekarang menggunakan fungsi signOut */}
        <button 
            onClick={() => signOut({ callbackUrl: '/login' })} 
            className="flex items-center w-full py-3 px-4 rounded-lg text-text-secondary hover:bg-gray-100 "
        >
          <LogOut className="w-5 h-5 mr-3" />
          Log Out
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;